select pg_temp.actor(3);insert into execution_ids values('order_policy',public.order_policy_command('prepare',jsonb_build_object('service_version_id',(select id from execution_ids where key='service'),'version',1,'valid_from',now()-interval '1 day','payment_gate','no_upfront_payment','offer_seconds',600,'performance_weight','1','workload_weight','1'),'laundry-order-policy'));
