select pg_temp.actor(4);select public.order_policy_command('approve',jsonb_build_object('id',(select id from execution_ids where key='order_policy')),'laundry-order-approve');select public.operation_policy_command('approve',jsonb_build_object('id',(select id from execution_ids where key='special_policy')),'laundry-special-approve');
select pg_temp.actor(6);insert into execution_ids values('request',public.create_service_request('a2000000-0000-0000-0000-000000000001',(select id from execution_ids where key='service'),'e3000000-0000-0000-0000-000000000001','{"details":[{"note":"Synthetic Laundry"}]}','laundry-request'));
select public.change_service_request((select id from execution_ids where key='request'),1,'submit');select pg_temp.actor(3);select public.review_service_request((select id from execution_ids where key='request'),2);
