set local role authenticated;select pg_temp.actor(8);select public.dispatch_command((select id from execution_ids where key='order'),'respond',jsonb_build_object('expected_revision',1,'offer_id',(select id from execution_ids where key='offer1'),'accept',true,'reason','Synthetic accept'),'laundry-accept1');select set_config('request.jwt.claim.sub','e1000000-0000-0000-0000-000000000002',true);select public.dispatch_command((select id from execution_ids where key='order'),'respond',jsonb_build_object('expected_revision',1,'offer_id',(select id from execution_ids where key='offer2'),'accept',true,'reason','Synthetic accept'),'laundry-accept2');
