create function pg_temp.lc(action text,data jsonb default '{}',p_key text default null) returns uuid language plpgsql as $$declare operation uuid;begin select id into operation from execution_ids where key='operation';return public.service_operation_command(operation,action,data||jsonb_build_object('expected_revision',(public.read_service_operation(operation)->>'revision')::integer,'reason','Synthetic Laundry command'),coalesce(p_key,gen_random_uuid()::text));end$$;
grant execute on function pg_temp.lc(text,jsonb,text) to authenticated;
insert into execution_ids values('operation',public.service_operation_command(null,'create',jsonb_build_object('order_id',(select id from execution_ids where key='order'),'kind','laundry','reason','Synthetic Laundry operation'),'laundry-operation'));
do $$declare code text;resource uuid;start_at timestamptz;finish_at timestamptz;task uuid;begin
foreach code in array array['pickup','process-a','process-b','delivery'] loop
 resource=(select id from execution_ids where key=case when code='process-a' then 'resource1' else 'resource2' end);
 start_at=(public.read_work_order((select id from execution_ids where key='work'))->>'start')::timestamptz;
 finish_at=(public.read_work_order((select id from execution_ids where key='work'))->>'end')::timestamptz;
 if code='pickup' then finish_at=start_at+interval '20 seconds';elsif code='process-b' then start_at=start_at+interval '20 seconds';finish_at=start_at+interval '40 seconds';elsif code='delivery' then start_at=start_at+interval '60 seconds';end if;
 task=pg_temp.fc('create_task',jsonb_build_object('resource_id',resource,'code',code,'description','Synthetic Laundry '||code,'start',start_at,'end',finish_at));insert into execution_ids values(code,task);
 perform pg_temp.lc('link_task',jsonb_build_object('task_id',task,'purpose',case when code='pickup' then 'pickup' when code='delivery' then 'laundry_delivery' else 'processing' end));
end loop;end$$;
insert into execution_ids values('bag',pg_temp.lc('bag.create','{"code":"SYNTHETIC-BAG-1","seal":"SEALED","condition":{"existing_stain":true}}'));
insert into execution_ids values('item1',pg_temp.lc('item.create',jsonb_build_object('bag_id',(select id from execution_ids where key='bag'),'reference','SYNTHETIC-SHIRTS-1','category','shirt','units',4,'tag','TAG-1','treatment','wash','condition','{"stain":"Declared at intake"}'::jsonb)));
insert into execution_ids values('item2',pg_temp.lc('item.create',jsonb_build_object('bag_id',(select id from execution_ids where key='bag'),'reference','SYNTHETIC-SHIRTS-2','category','shirt','units',4,'tag','TAG-2','treatment','wash','condition','{}'::jsonb)));
select pg_temp.actor(6);select pg_temp.lc('bag.acknowledge',jsonb_build_object('id',(select id from execution_ids where key='bag')));select pg_temp.actor(3);select pg_temp.lc('activate');
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.lc('item.create',jsonb_build_object('bag_id',(select id from execution_ids where key='bag'),'reference','BAD','category','shirt','units',1,'tag','BAD','treatment','wash','condition','{}'::jsonb))$q$,'42501'),'Customer-acknowledged intake counts cannot be changed');
-- Every attachment uses shared quarantined uploads and independent evidence review.
do $$declare code text;proof uuid;begin foreach code in array array['pickup','process-a','process-b','delivery'] loop
 perform pg_temp.actor(case when code='process-a' then 2 else 1 end);
 proof=pg_temp.fc('prepare_upload',jsonb_build_object('task_id',(select id from execution_ids where key=code),'classification','completion','content_type','image/jpeg','byte_size',1024));insert into execution_ids values('evidence-'||code,proof);
end loop;end$$;
