select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.lc('custody.receive',pg_temp.receive_all((select id from execution_ids where key='pickup-transfer')))$q$,'42501'),'Rejected transfer cannot later be acknowledged as received');
